func TestCheck(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/repos/flipt-io/flipt/releases/latest" {
			t.Errorf("unexpected path: %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"tag_name":"v1.3.0","html_url":"https://example.com/v1.3.0"}`))
	}))
	defer server.Close()

	client := github.NewClient(server.Client())
	baseURL, err := url.Parse(server.URL + "/")
	if err != nil {
		t.Fatal(err)
	}
	client.BaseURL = baseURL

	for _, tt := range []struct {
		current string
		update  bool
	}{
		{"v1.2.0", true},
		{"v1.3.0", false},
		{"v1.4.0", false},
	} {
		got, err := check(context.Background(), tt.current, client)
		if err != nil {
			t.Fatal(err)
		}
		if got.CurrentVersion != tt.current || got.LatestVersion != "v1.3.0" || got.LatestVersionURL != "https://example.com/v1.3.0" || got.UpdateAvailable != tt.update {
			t.Fatalf("check(%q) = %+v", tt.current, got)
		}
	}
}

